      "sections": [
        {
          "heading": "1. Bộ 4 Thì Hiện Tại",
          "content": "• Hiện tại đơn (S + V(s/es)): Sự thật hiển nhiên, thói quen lặp lại (always, usually, every day).\n• Hiện tại tiếp diễn (S + am/is/are + V-ing): Đang xảy ra lúc nói (now, at the moment, Look!, Listen!).\n• Hiện tại hoàn thành (S + have/has + V3/ed): Hành động xảy ra quá khứ kéo dài đến hiện tại (since, for, already, yet, just, ever).\n• Hiện tại HTTD (S + have/has been + V-ing): Nhấn mạnh tính liên tục của hành động (since yesterday, for 2 hours now)."
        },
        {
          "heading": "2. Bộ 4 Thì Quá Khứ",
          "content": "• Quá khứ đơn (S + V2/ed): Chấm dứt hoàn toàn trong quá khứ có mốc thời gian (yesterday, ago, last week, in 1990).\n• Quá khứ tiếp diễn (S + was/were + V-ing): Đang xảy ra tại thời điểm xác định trong quá khứ (at 8 PM yesterday, while, when).\n• Quá khứ hoàn thành (S + had + V3/ed): Xảy ra TRƯỚC một hành động khác trong quá khứ (before, after, by the time).\n• Quá khứ HTTD (S + had been + V-ing): Nhấn mạnh tính liên tục trước một thời điểm quá khứ."
        },
        {
          "heading": "3. Bộ 5 Cấu Trúc Tương Lai & Sắc Thái Phân Biệt",
          "content": "• Will + V: Quyết định tức thì lúc nói, lời hứa, dự đoán chủ quan (I think, probably, promise).\n• Be going to + V: Dự định có từ trước, hoặc dự đoán CÓ BẰNG CHỨNG thực tế (Look at those dark clouds! It is going to rain).\n• Hiện tại tiếp diễn (be + V-ing): Kế hoạch chắc chắn 100% đã ấn định thời gian, địa điểm, có vé/lịch hẹn.\n• Tương lai tiếp diễn (will be + V-ing): Đang diễn ra tại thời điểm xác định trong tương lai (at this time tomorrow).\n• Tương lai hoàn thành (will have + V3/ed): Hoàn tất TRƯỚC một mốc tương lai (by tomorrow, by next week)."
        }
      ],
      "tips": "🌸 Mẹo vàng cho Trâm: Nhìn thấy 'By + mốc tương lai' -> chọn Will have V3. Nhìn thấy 'Since' -> chọn Have/has V3. Nhìn thấy 'Yesterday/ago' -> chọn V2/ed!"
